abel><input name="fecha_ingreso" type="date" class="input" value="<?= e($value('fecha_ingreso')) ?>" required><?= field_error('fecha_ingreso') ?></div><div class="sm:col-span-2 flex justify-end gap-3"><a href="<?= e(url('/equipo')) ?>" class="btn-secondary">Cancelar</a><button type="submit" class="btn-primary">Guardar cambios</button></div></form></div>
